    "credit": "Salahuddin Ahmed",
    "license": "Unsplash",
    "link": "https://unsplash.com/photos/a-yellow-medical-sensor-attached-to-a-persons-arm-tIEsUnmLaKY?utm_source=dia_news&utm_medium=referral",
