    "credit": "Vitaly Gariev",
    "license": "Unsplash",
    "link": "https://unsplash.com/photos/doctor-wearing-a-stethoscope-sits-at-a-desk-JJEOuvnY1Tw?utm_source=dia_news&utm_medium=referral",
